<section id="branchManagement" hidden aria-label="Gestión de sucursales">
<div class="branch-admin-toolbar"><label class="branch-admin-search"><?= stock_icon('search') ?><input id="manageBranchSearch" type="search" maxlength="160" placeholder="Nombre, dirección o provincia" aria-label="Buscar sucursales"></label><button id="manageBranchAdd" class="library-primary stock-icon" type="button" title="Agregar sucursal" aria-label="Agregar sucursal"><?= stock_icon('plus') ?></button></div>
<p id="manageBranchStatus" class="library-status" role="status"></p><div id="manageBranchList"></div><div id="manageBranchPages" class="library-dialog-actions" hidden><button id="manageBranchPrevious" type="button" class="library-secondary" aria-label="Página anterior"><?= stock_icon('chevron') ?></button><span id="manageBranchPage"></span><button id="manageBranchNext" type="button" class="library-secondary" aria-label="Página siguiente"><?= stock_icon('chevron') ?></button></div>
</section>
<dialog id="manageBranchDialog" class="library-dialog branch-dialog" aria-labelledby="manageBranchTitle"><div class="library-heading"><h2 id="manageBranchTitle"><?= stock_icon('branch') ?> <span>Editar sucursal</span></h2><button type="button" class="app-close" id="manageBranchClose" aria-label="Cerrar"><?= stock_icon('close') ?></button></div><p id="manageBranchNotice" class="library-status" role="status"></p><form id="manageBranchForm"><label>Nombre<input name="name" required maxlength="100" placeholder="Ej.: Carrefour Centro"></label><div id="manageBranchMatches" class="branch-admin-matches" hidden></div><label>Dirección<input name="address" required maxlength="160" placeholder="Ej.: Av. Colón 1234"></label><div class="branch-form-row"><label>Localidad<input name="locality" required maxlength="100" placeholder="Ej.: Córdoba"></label><label>Provincia<input name="province" required maxlength="80" placeholder="Ej.: Córdoba"></label></div><label>Descripción <small>(opcional)</small><textarea name="description" maxlength="300" rows="2" placeholder="Ej.: Entrada por la calle lateral"></textarea></label><input name="latitude" type="hidden"><input name="longitude" type="hidden"><details id="manageBranchLocation" class="branch-point-details"><summary><?= stock_icon('branch') ?> Ubicación en el mapa<span class="branch-create-chevron"><?= stock_icon('chevron') ?></span></summary><div id="manageBranchMap" class="branch-map"></div><p id="manageBranchMapStatus" class="stock-muted" role="status"></p><button id="manageBranchClearPoint" type="button" class="library-secondary">Quitar ubicación</button></details><button type="submit" class="library-primary"><?= stock_icon('check') ?> Guardar cambios</button></form></dialog>
